      hu: ["Fénykora i. sz. 900 és 1450 közé tehető", "Többszintes vályogépületekből álló város", "1998 óta az UNESCO Világörökség része", "Ara papagájokat tenyésztettek rituális célokra", "Bonyolult csatorna- és vízhálózatot építettek", "Chihuahua államban, a Casas Grandes folyó mellett fekszik"],
