      en: ["Flourished between the years 900 and 1450 AD", "Features multi-story residential adobe structures", "UNESCO World Heritage Site since 1998", "Evidence found of large-scale macaw breeding", "Had a highly advanced water distribution system", "Located in the modern state of Chihuahua, Mexico"],
      es: ["Es famoso por su compleja arquitectura de adobe (construcción de tierra) de varios pisos.", "Funcionó como un centro comercial central entre Mesoamérica y las culturas pueblo.", "Contaba con un sistema sorprendentemente moderno de suministro de agua y calefacción de espacios."],
      pt: ["É famoso pela sua complexa arquitetura de adobe (construção em terra) de vários andares.", "Funcionou como um nó comercial central entre a Mesoamérica e as culturas pueblo.", "Possuía um sistema surpreendentemente moderno de abastecimento de água e aquecimento de espaços."],
      fr: ["Célèbre pour son architecture complexe en adobe (terre crue) sur plusieurs étages.", "Servait de plaque tournante commerciale entre la Mésoamérique et les cultures Pueblo.", "Disposait d'un système étonnamment moderne d'approvisionnement en eau et de chauffage des pièces."],
